import Link from 'next/link'

import type { NotionIndexPage } from '@/lib/notion-index'
import { categoryForTitle, iconForTitle } from '@/lib/wiki-taxonomy'
import { wikiContentStatus } from '@/lib/wiki-content-status'
import {
  deriveOptimizedVariant,
  resolveCachedAsset,
  withBasePath
} from '@/lib/url-utils'

function badgeForTitle(title: string) {
  if (title === '서버규칙' || title.includes('뉴비필독')) return '필수'
  if (title === '채광' || title === '빚 갚기' || title === '장비강화') return '핵심'
  if (title === '패치노트') return '업데이트'
  if (title === '많이 물어보는 것') return 'FAQ'
  if (title === 'API') return 'API'
  return null
}

const DESCRIPTION_BY_TITLE: Record<string, string> = {
  스토리: '서버 세계관과 시작 배경',
  서버규칙: '플레이 전 반드시 확인할 운영 규칙',
  패치노트: '최근 변경점과 업데이트 기록',
  API: '후원·API 연동 관련 안내',
  '기초설정(뉴비필독)': '첫 접속 전에 끝내야 할 필수 설정',
  채광: '광물 채집·판매·초반 수익 안내',
  낚시: '낚시 시스템과 보상 안내',
  도축: '도축 시스템과 재료 획득 안내',
  사냥: '전투·몬스터·사냥 보상 안내',
  요리: '재료 활용과 요리 시스템 안내',
  도감: '수집 도감과 달성 보상 안내',
  파쿠르: '파쿠르 진행과 보상 안내',
  즉석복권: '복권 이용 방법과 보상 안내',
  경마장: '경마장 이용 방법과 시스템 안내',
  카지노: '카지노 게임과 이용 방법 안내',
  '땅 구매': '토지 구매와 소유 시스템 안내',
  '빚 갚기': '부채 상환과 경제 진행 흐름',
  신용등급: '신용등급 조건과 혜택 안내',
  장비수리: '장비 내구도와 수리 방법 안내',
  장비강화: '강화 단계·재료·성장 안내',
  '많이 물어보는 것': '자주 묻는 질문을 빠르게 확인'
}

const FEATURED = new Set(['서버규칙','기초설정(뉴비필독)','채광','빚 갚기','장비강화'])

const GROUPS = [
  { key: 'start', icon: '🧭', title: '시작하기', description: '처음 접속하기 전에 확인할 필수 안내' },
  { key: 'content', icon: '🎮', title: '주요 콘텐츠', description: '채광부터 도감·파쿠르·미니게임까지' },
  { key: 'growth', icon: '📈', title: '성장 · 경제', description: '땅, 빚, 신용등급, 장비 성장과 FAQ' }
] as const

function mediaIdentity(value: string) {
  const filename = value.split('/').pop() || value
  return filename.replace(/\.[a-z0-9]+$/i, '')
}

function isCardThumbnail(value?: string | null): value is string {
  return Boolean(value && (/\/optimized\/thumb256\//.test(value) || /\/optimized\/thumb\//.test(value)))
}

function assignUniqueMedia(pages: NotionIndexPage[]) {
  const used = new Set<string>()
  const mediaById = new Map<string, string | null>()
  for (const page of pages) {
    const derivedSmall = deriveOptimizedVariant(page.thumbnail, 'thumb256')
    const candidates = [
      page.thumbnailSmall,
      derivedSmall,
      page.thumbnail
    ].filter(isCardThumbnail)
    const media = candidates.find((value) => !used.has(mediaIdentity(value))) ?? null
    if (media) used.add(mediaIdentity(media))
    mediaById.set(page.pageId, media)
  }
  return mediaById
}

export function WikiDirectory({ pages }: { pages: NotionIndexPage[] }) {
  if (!pages.length) return null
  const mediaById = assignUniqueMedia(pages)
  const grouped = GROUPS.map((group) => {
    const groupPages = pages.filter(
      (page) => categoryForTitle(page.title) === group.key
    )
    return {
      ...group,
      pages: groupPages,
      readyPages: groupPages.filter(
        (page) => wikiContentStatus(page) !== 'draft'
      ),
      draftPages: groupPages.filter(
        (page) => wikiContentStatus(page) === 'draft'
      )
    }
  }).filter((group) => group.pages.length > 0)

  const counts = pages.reduce(
    (acc, page) => {
      acc[wikiContentStatus(page)] += 1
      return acc
    },
    { detailed: 0, brief: 0, draft: 0 }
  )

  return (
    <section className="wiki-directory" aria-labelledby="wiki-directory-title">
      <div className="directory-heading">
        <div>
          <p>QUICK DIRECTORY</p>
          <h2 id="wiki-directory-title">위키 가이드 바로가기</h2>
          <span>이미지와 아이콘만 봐도 문서를 빠르게 구분할 수 있게 정리했습니다.</span>
        </div>
        <span>
          상세 {counts.detailed} · 간단 {counts.brief} · 작성 중 {counts.draft}
        </span>
      </div>

      <div className="directory-groups">
        {grouped.map((group) => (
          <section className="directory-group" data-category={group.key} id={`category-${group.key}`} key={group.key}>
            <div className="directory-group-head">
              <span>{group.icon}</span>
              <div>
                <strong>{group.title}</strong>
                <small>{group.description}</small>
              </div>
              <em>{group.pages.length}</em>
            </div>

            <div className="directory-grid">
              {group.readyPages.map((page) => {
                const media = mediaById.get(page.pageId) ?? null
                const resolvedMedia = media ? resolveCachedAsset(media) : null
                const status = wikiContentStatus(page)
                const badge =
                  status === 'brief'
                    ? '간단 안내'
                    : badgeForTitle(page.title)
                const featured =
                  FEATURED.has(page.title) && status === 'detailed'

                return (
                  <Link
                    key={page.pageId}
                    href={withBasePath(`/page/${page.pageId}/`)}
                    prefetch={false}
                    className={`directory-card ${featured ? 'is-featured' : ''} ${status === 'brief' ? 'is-brief' : ''}`}
                    data-status={status}
                  >
                    <span className={`directory-media ${media ? 'has-image' : 'is-icon'}`}>
                      {resolvedMedia ? (
                        <img src={resolvedMedia} alt="" aria-hidden="true" loading="lazy" decoding="async" width="256" height="256" />
                      ) : (
                        iconForTitle(page.title)
                      )}
                    </span>

                    <span className="directory-copy">
                      <span className="directory-title-row">
                        <strong>{page.title}</strong>
                        {badge && <em>{badge}</em>}
                      </span>
                      <small>
                        {DESCRIPTION_BY_TITLE[page.title] ||
                          (featured
                            ? '처음이라면 꼭 확인하세요'
                            : status === 'brief'
                              ? '핵심 내용만 간단히 정리된 안내입니다.'
                              : '상세 가이드 열기')}
                      </small>
                    </span>

                    <span className="directory-arrow">↗</span>
                  </Link>
                )
              })}
            </div>

            {group.draftPages.length > 0 && (
              <details className="directory-drafts">
                <summary>
                  <span>작성 중인 문서 {group.draftPages.length}개</span>
                  <small>필요할 때 펼쳐보세요</small>
                </summary>
                <div className="directory-grid is-drafts">
                  {group.draftPages.map((page) => {
                    const media = mediaById.get(page.pageId) ?? null
                    const resolvedMedia = media
                      ? resolveCachedAsset(media)
                      : null

                    return (
                      <Link
                        key={page.pageId}
                        href={withBasePath(`/page/${page.pageId}/`)}
                        prefetch={false}
                        className="directory-card is-draft"
                        data-status="draft"
                      >
                        <span className={`directory-media ${media ? 'has-image' : 'is-icon'}`}>
                          {resolvedMedia ? (
                            <img src={resolvedMedia} alt="" aria-hidden="true" loading="lazy" decoding="async" width="256" height="256" />
                          ) : (
                            iconForTitle(page.title)
                          )}
                        </span>
                        <span className="directory-copy">
                          <span className="directory-title-row">
                            <strong>{page.title}</strong>
                            <em>작성 중</em>
                          </span>
                          <small>내용을 정리하고 있습니다.</small>
                        </span>
                        <span className="directory-arrow">↗</span>
                      </Link>
                    )
                  })}
                </div>
              </details>
            )}
          </section>
        ))}
      </div>
    </section>
  )
}

'use client'

import { track } from '@vercel/analytics'

import { buildWikiFeedbackUrl } from '@/lib/wiki-ux'

export function WikiDocumentFeedback({
  pageId,
  title
}: {
  pageId: string
  title: string
}) {
  const items = [
    {
      kind: 'incorrect' as const,
      label: '잘못된 정보 제보',
      description: '틀렸거나 오래된 내용을 알려주세요.'
    },
    {
      kind: 'improve' as const,
      label: '내용 보강 요청',
      description: '추가되면 좋은 정보를 요청할 수 있습니다.'
    }
  ]

  return (
    <aside className="document-feedback" aria-labelledby="document-feedback-title">
      <div>
        <p>HELP IMPROVE THIS WIKI</p>
        <h2 id="document-feedback-title">문서 개선 제보</h2>
        <span>
          수정이 필요한 부분을 발견했다면 문서 정보가 미리 채워진 제보 창을 열 수 있습니다.
        </span>
      </div>

      <div className="document-feedback-actions">
        {items.map((item) => (
          <a
            key={item.kind}
            href={buildWikiFeedbackUrl({
              pageId,
              title,
              kind: item.kind
            })}
            target="_blank"
            rel="noreferrer noopener"
            onClick={() =>
              track('wiki_feedback_open', {
                kind: item.kind,
                page_id: pageId.replaceAll('-', '')
              })
            }
          >
            <strong>{item.label}</strong>
            <small>{item.description}</small>
            <b aria-hidden="true">↗</b>
          </a>
        ))}
      </div>
    </aside>
  )
}

'use client'

import Link from 'next/link'

import { iconForTitle } from '@/lib/wiki-taxonomy'
import { withBasePath } from '@/lib/url-utils'

export type WikiNavigationPage = {
  pageId: string
  title: string
  category?: string
}

export type WikiNavigationTocItem = {
  id: string
  text: string
  level: number
}

export function WikiNavigation({
  pages,
  currentPageId,
  currentCategory,
  openMobileCategories,
  onToggleMobileCategory,
  menuOpen,
  onCloseMenu,
  home,
  toc,
  activeTocId,
  onNavigateToc,
  readingProgress,
  sidebarCollapsed,
  onToggleSidebar,
  onOpenSearch,
  categoryForPage
}: {
  pages: WikiNavigationPage[]
  currentPageId?: string | null
  currentCategory: string
  openMobileCategories: string[]
  onToggleMobileCategory: (category: string) => void
  menuOpen: boolean
  onCloseMenu: () => void
  home: boolean
  toc: WikiNavigationTocItem[]
  activeTocId: string
  onNavigateToc: (id: string) => void
  readingProgress: number
  sidebarCollapsed: boolean
  onToggleSidebar: () => void
  onOpenSearch: () => void
  categoryForPage: (page: WikiNavigationPage) => string
}) {
  return (
    <>
      <aside className={`wiki-sidebar ${menuOpen ? 'is-open' : ''}`}>
        <div className="sidebar-head">
          <strong>문서 탐색</strong>
          <span>{pages.length}개</span>
        </div>

        {!home && (
          <button
            className="wiki-search wiki-search-trigger"
            type="button"
            aria-keyshortcuts="Control+K Meta+K /"
            onClick={onOpenSearch}
          >
            <span>⌕</span>
            <span>전체 문서 검색</span>
            <kbd>⌘K</kbd>
          </button>
        )}

        <div className="sidebar-primary-links">
          <Link
            className="sidebar-home"
            href={withBasePath('/')}
            prefetch={false}
            onClick={onCloseMenu}
          >
            <span>🏠</span>
            위키 홈
          </Link>
        </div>

        <nav className="toc-list">
          <div className="global-page-list">
            <span className="nav-section-label">전체 문서</span>
            {['시작하기', '주요 콘텐츠', '성장 · 경제'].map((group) => {
              const groupPages = pages.filter(
                (page) => categoryForPage(page) === group
              )

              if (!groupPages.length) return null

              return (
                <section
                  className={`sidebar-category ${openMobileCategories.includes(group) ? 'is-mobile-open' : ''}`}
                  key={group}
                >
                  <div className="sidebar-category-head sidebar-category-head-static">
                    <strong>{group}</strong>
                    <span className="sidebar-category-meta">
                      <span>{groupPages.length}</span>
                    </span>
                  </div>
                  <button
                    type="button"
                    className="sidebar-category-head sidebar-category-head-toggle"
                    aria-expanded={openMobileCategories.includes(group)}
                    onClick={() => onToggleMobileCategory(group)}
                  >
                    <strong>{group}</strong>
                    <span className="sidebar-category-meta">
                      <span>{groupPages.length}</span>
                      <b aria-hidden="true">⌄</b>
                    </span>
                  </button>
                  <div className="sidebar-category-links">
                    {groupPages.map((page) => {
                      const current =
                        Boolean(currentPageId) &&
                        page.pageId.replaceAll('-', '') ===
                          currentPageId!.replaceAll('-', '')

                      return (
                        <Link
                          key={page.pageId}
                          href={withBasePath(`/page/${page.pageId}/`)}
                          prefetch={false}
                          onClick={onCloseMenu}
                          className={`global-page-link ${current ? 'is-current' : ''}`}
                          aria-current={current ? 'page' : undefined}
                        >
                          <span className="sidebar-page-icon" aria-hidden="true">
                            {iconForTitle(page.title)}
                          </span>
                          <span className="global-page-copy">
                            <strong>{page.title}</strong>
                          </span>
                        </Link>
                      )
                    })}
                  </div>
                </section>
              )
            })}
          </div>

          <div className="current-toc mobile-current-toc">
            <span className="nav-section-label">
              현재 페이지{currentCategory ? ` · ${currentCategory}` : ''}
            </span>
            {toc.length ? (
              toc.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  className={`toc-item level-${item.level} ${activeTocId === item.id ? 'is-active' : ''}`}
                  aria-current={activeTocId === item.id ? 'location' : undefined}
                  onClick={() => onNavigateToc(item.id)}
                >
                  <span>{iconForTitle(item.text)}</span>
                  <span>{item.text}</span>
                </button>
              ))
            ) : (
              <p className="toc-empty">현재 페이지 목차가 없습니다.</p>
            )}
          </div>
        </nav>

        <div className="sidebar-foot">
          <span className="live-dot" />
          공식 가이드 문서
        </div>
      </aside>

      <button
        className="sidebar-edge-toggle"
        type="button"
        aria-label={sidebarCollapsed ? '문서 목록 펼치기' : '문서 목록 접기'}
        aria-pressed={sidebarCollapsed}
        title={sidebarCollapsed ? '문서 목록 펼치기' : '문서 목록 접기'}
        onClick={onToggleSidebar}
      >
        <span className="sidebar-toggle-expanded" aria-hidden="true">‹</span>
        <span className="sidebar-toggle-collapsed" aria-hidden="true">
          <b>☰</b><em>문서</em>
        </span>
      </button>

      {menuOpen && (
        <button
          className="sidebar-backdrop"
          type="button"
          aria-label="메뉴 닫기"
          onClick={onCloseMenu}
        />
      )}

      {!home && toc.length > 0 && (
        <aside className="article-toc" aria-label="현재 문서 목차">
          <div className="article-progress">
            <span>읽는 중</span>
            <strong>{readingProgress}%</strong>
          </div>
          <div className="article-progress-track" aria-hidden="true">
            <span style={{ height: `${readingProgress}%` }} />
          </div>
          <span className="article-toc-label">이 페이지에서</span>
          <nav>
            {toc.map((item) => (
              <button
                key={item.id}
                type="button"
                className={`article-toc-item level-${item.level} ${activeTocId === item.id ? 'is-active' : ''}`}
                aria-current={activeTocId === item.id ? 'location' : undefined}
                onClick={() => onNavigateToc(item.id)}
              >
                {item.text}
              </button>
            ))}
          </nav>
        </aside>
      )}
    </>
  )
}

import Link from 'next/link'

import type { NotionIndexPage } from '@/lib/notion-index'
import { categoryAnchorForTitle, categoryTitleForPage } from '@/lib/wiki-taxonomy'
import { withBasePath } from '@/lib/url-utils'

function formatDate(value: string | null) {
  if (!value) return null
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return null
  return new Intl.DateTimeFormat('ko-KR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date)
}

export function WikiPageNavigation({
  current,
  pages,
  mode = 'context'
}: {
  current: NotionIndexPage | null
  pages: NotionIndexPage[]
  mode?: 'context' | 'siblings'
}) {
  if (!current) return null

  const currentIndex = pages.findIndex((page) => page.pageId === current.pageId)
  const previous = currentIndex > 0 ? pages[currentIndex - 1] : null
  const next =
    currentIndex >= 0 && currentIndex < pages.length - 1
      ? pages[currentIndex + 1]
      : null
  const category = categoryTitleForPage(current.title)
  const updatedAt = formatDate(current.lastEdited)

  if (mode === 'siblings') {
    return (
      <nav className="page-siblings page-siblings-bottom" aria-label="이전 및 다음 문서">
        {previous ? (
          <Link href={withBasePath(`/page/${previous.pageId}/`)}>
            <small>← 이전 문서</small>
            <strong>{previous.title}</strong>
          </Link>
        ) : (
          <span />
        )}

        {next ? (
          <Link
            href={withBasePath(`/page/${next.pageId}/`)}
            className="page-sibling-next"
          >
            <small>다음 문서 →</small>
            <strong>{next.title}</strong>
          </Link>
        ) : (
          <span />
        )}
      </nav>
    )
  }

  return (
    <div className="page-context">
      <nav className="breadcrumbs" aria-label="현재 위치">
        <Link href={withBasePath('/')} prefetch={false}>위키 홈</Link>
        <span>›</span>
        <Link href={withBasePath(`/#${categoryAnchorForTitle(current.title)}`)} prefetch={false}>{category}</Link>
        <span>›</span>
        <strong>{current.title}</strong>
      </nav>
      {updatedAt && <span className="page-updated">최근 수정 {updatedAt}</span>}
    </div>
  )
}

'use client'

import Link from 'next/link'
import { track } from '@vercel/analytics'
import { useEffect, useRef } from 'react'

import { iconForTitle } from '@/lib/wiki-taxonomy'
import { withBasePath } from '@/lib/url-utils'

export type ReadingTocItem = {
  id: string
  text: string
  level: number
}

type RecentPage = {
  pageId: string
  title: string
}

export function RecentViewedSection({
  ready,
  pages,
  onClear
}: {
  ready: boolean
  pages: RecentPage[]
  onClear: () => void
}) {
  return (
    <section
      className={`recent-viewed ${!ready ? 'is-loading' : pages.length ? '' : 'is-empty'}`}
      aria-labelledby="recent-viewed-title"
      aria-busy={!ready}
    >
      <div className="recent-viewed-head">
        <div>
          <p>RECENTLY VIEWED</p>
          <h2 id="recent-viewed-title">최근 본 문서</h2>
        </div>
        <div className="recent-viewed-actions">
          <small>이 브라우저에만 저장됩니다.</small>
          {ready && pages.length > 0 && (
            <button type="button" onClick={onClear}>
              기록 지우기
            </button>
          )}
        </div>
      </div>

      {!ready ? (
        <div
          className="recent-viewed-list recent-viewed-loading"
          aria-hidden="true"
        >
          {Array.from({ length: 3 }).map((_, index) => (
            <span className="recent-viewed-skeleton" key={index} />
          ))}
        </div>
      ) : pages.length > 0 ? (
        <div className="recent-viewed-list">
          {pages.map((page) => (
            <Link
              key={page.pageId}
              href={withBasePath(`/page/${page.pageId}/`)}
              className="recent-viewed-card"
            >
              <span aria-hidden="true">{iconForTitle(page.title)}</span>
              <strong>{page.title}</strong>
              <b>→</b>
            </Link>
          ))}
        </div>
      ) : (
        <p className="recent-viewed-empty">
          아직 본 문서가 없습니다. 가이드를 열면 최근 기록이 여기에 표시됩니다.
        </p>
      )}
    </section>
  )
}

export function MobileTocSheet({
  toc,
  readingProgress,
  activeTocId,
  onClose,
  onNavigate
}: {
  toc: ReadingTocItem[]
  readingProgress: number
  activeTocId: string
  onClose: () => void
  onNavigate: (id: string) => void
}) {
  const sheetRef = useRef<HTMLElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)

  useEffect(() => {
    track('wiki_mobile_toc_open')
    returnFocusRef.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null

    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const frame = requestAnimationFrame(() => closeRef.current?.focus())

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        onClose()
        return
      }

      if (event.key !== 'Tab' || !sheetRef.current) return

      const focusable = Array.from(
        sheetRef.current.querySelectorAll<HTMLElement>(
          'button, a[href], [tabindex]:not([tabindex="-1"])'
        )
      ).filter((element) => !element.hasAttribute('disabled'))

      if (!focusable.length) return

      const first = focusable[0]
      const last = focusable[focusable.length - 1]

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    window.addEventListener('keydown', onKeyDown)

    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener('keydown', onKeyDown)
      document.body.style.overflow = previousOverflow
      requestAnimationFrame(() => returnFocusRef.current?.focus())
    }
  }, [onClose])

  return (
    <div
      className="mobile-toc-backdrop"
      role="presentation"
      onMouseDown={(event) => {
        if (event.currentTarget === event.target) onClose()
      }}
    >
      <section
        ref={sheetRef}
        className="mobile-toc-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="mobile-toc-title"
      >
        <div className="mobile-toc-handle" aria-hidden="true" />
        <header>
          <div>
            <small>현재 문서</small>
            <strong id="mobile-toc-title">목차</strong>
          </div>
          <button
            ref={closeRef}
            type="button"
            aria-label="목차 닫기"
            onClick={onClose}
          >
            ×
          </button>
        </header>
        <div className="mobile-toc-progress">
          <span>읽는 중</span>
          <b>{readingProgress}%</b>
        </div>
        <nav>
          {toc.map((item) => (
            <button
              key={item.id}
              type="button"
              className={`mobile-toc-item level-${item.level} ${activeTocId === item.id ? 'is-active' : ''}`}
              aria-current={activeTocId === item.id ? 'location' : undefined}
              onClick={() => {
                track('wiki_mobile_toc_navigate')
                onNavigate(item.id)
              }}
            >
              <span>{iconForTitle(item.text)}</span>
              <strong>{item.text}</strong>
            </button>
          ))}
        </nav>
      </section>
    </div>
  )
}

